#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IconId {
    OrnamentLeft,
    OrnamentRight,
    Logo,
    FlagBd,
    FlagEn,
    Keyboard,
    Gear,
    Info,
    Menu,
}

struct CachedIcon {
    hdc: HDC,
    hbm: HBITMAP,
    w: i32,
    h: i32,
}

static mut ICONS: [Option<CachedIcon>; 9] = [None, None, None, None, None, None, None, None, None];
static mut TRAY_ICONS: [HICON; 4] = [0, 0, 0, 0];

pub unsafe fn init_assets(screen_dc: HDC) {
    let icon_defs: [(IconId, i32, i32, &[u8]); 9] = [
        (IconId::OrnamentLeft, ORN_LEFT_W, ORN_LEFT_H, ORN_LEFT_DATA),
        (IconId::OrnamentRight, ORN_RIGHT_W, ORN_RIGHT_H, ORN_RIGHT_DATA),
        (IconId::Logo, LOGO_W, LOGO_H, LOGO_DATA),
        (IconId::FlagBd, FLAG_BD_W, FLAG_BD_H, FLAG_BD_DATA),
        (IconId::FlagEn, FLAG_EN_W, FLAG_EN_H, FLAG_EN_DATA),
        (IconId::Keyboard, KEYBOARD_W, KEYBOARD_H, KEYBOARD_DATA),
        (IconId::Gear, GEAR_W, GEAR_H, GEAR_DATA),
        (IconId::Info, INFO_W, INFO_H, INFO_DATA),
        (IconId::Menu, MENU_W, MENU_H, MENU_DATA),
    ];

    for (idx, &(_, w, h, data)) in icon_defs.iter().enumerate() {
        let mem_dc = CreateCompatibleDC(screen_dc);
        let mut bmi: BITMAPINFO = std::mem::zeroed();
        bmi.bmiHeader.biSize = std::mem::size_of::<BITMAPINFOHEADER>() as u32;
        bmi.bmiHeader.biWidth = w;
        bmi.bmiHeader.biHeight = -h; // Top-down
        bmi.bmiHeader.biPlanes = 1;
        bmi.bmiHeader.biBitCount = 32;
        bmi.bmiHeader.biCompression = BI_RGB;

        let mut ppv_bits: *mut c_void = std::ptr::null_mut();
        let hbm = CreateDIBSection(mem_dc, &bmi, DIB_RGB_COLORS, &mut ppv_bits, 0, 0);
        if !ppv_bits.is_null() && !data.is_empty() {
            std::ptr::copy_nonoverlapping(data.as_ptr(), ppv_bits as *mut u8, data.len().min((w * h * 4) as usize));
        }
        SelectObject(mem_dc, hbm);
        ICONS[idx] = Some(CachedIcon { hdc: mem_dc, hbm, w, h });
    }

    // Initialize Tray HICONs (Unicode, Ansi, Phonetic, English)
    let tray_defs = [
        TRAY_UNI_DATA,  // 0: Unicode
        TRAY_ANSI_DATA, // 1: Ansi
        TRAY_PHO_DATA,  // 2: Phonetic
        TRAY_EN_DATA,   // 3: English
    ];

    for (mode, &data) in tray_defs.iter().enumerate() {
        TRAY_ICONS[mode] = create_hicon_from_bgra(32, 32, data);
    }
}

pub unsafe fn draw_icon(hdc_dest: HDC, id: IconId, x: i32, y: i32) {
    let idx = match id {
        IconId::OrnamentLeft => 0,
        IconId::OrnamentRight => 1,
        IconId::Logo => 2,
        IconId::FlagBd => 3,
        IconId::FlagEn => 4,
        IconId::Keyboard => 5,
        IconId::Gear => 6,
        IconId::Info => 7,
        IconId::Menu => 8,
    };

    if let Some(ref icon) = ICONS[idx] {
        let blend = BLENDFUNCTION {
            BlendOp: AC_SRC_OVER,
            BlendFlags: 0,
            SourceConstantAlpha: 255,
            AlphaFormat: AC_SRC_ALPHA,
        };
        AlphaBlend(hdc_dest, x, y, icon.w, icon.h, icon.hdc, 0, 0, icon.w, icon.h, blend);
    }
}

pub unsafe fn get_tray_hicon(mode: u32) -> HICON {
    let idx = (mode as usize).min(3);
    TRAY_ICONS[idx]
}

unsafe fn create_hicon_from_bgra(w: i32, h: i32, bgra: &[u8]) -> HICON {
    let screen_dc = super::toolbar::FloatingToolbar::get_hwnd();
    let dc = CreateCompatibleDC(0);
    let mut bmi: BITMAPINFO = std::mem::zeroed();
    bmi.bmiHeader.biSize = std::mem::size_of::<BITMAPINFOHEADER>() as u32;
    bmi.bmiHeader.biWidth = w;
    bmi.bmiHeader.biHeight = -h;
    bmi.bmiHeader.biPlanes = 1;
    bmi.bmiHeader.biBitCount = 32;
    bmi.bmiHeader.biCompression = BI_RGB;

    let mut ppv: *mut c_void = std::ptr::null_mut();
    let hbm_color = CreateDIBSection(dc, &bmi, DIB_RGB_COLORS, &mut ppv, 0, 0);
    if !ppv.is_null() && !bgra.is_empty() {
        std::ptr::copy_nonoverlapping(bgra.as_ptr(), ppv as *mut u8, bgra.len().min((w * h * 4) as usize));
    }

    // 1-bit mask bitmap
    let hbm_mask = CreateBitmap(w, h, 1, 1, std::ptr::null());

    let icon_info = ICONINFO {
        fIcon: TRUE,
        xHotspot: 0,
        yHotspot: 0,
        hbmMask: hbm_mask,
        hbmColor: hbm_color,
    };

    let hicon = CreateIconIndirect(&icon_info);

    DeleteObject(hbm_color);
    DeleteObject(hbm_mask);
    DeleteDC(dc);

    hicon
}

pub unsafe fn cleanup_assets() {
    for slot in ICONS.iter_mut() {
        if let Some(icon) = slot.take() {
            DeleteObject(icon.hbm);
            DeleteDC(icon.hdc);
        }
    }
    for hicon in TRAY_ICONS.iter_mut() {
        if *hicon != 0 {
            DestroyIcon(*hicon);
            *hicon = 0;
        }
    }
}
